#!/usr/bin/env node
/**
 * Validate that the UI stays on the design system.
 *
 * Checks:
 *   1. src/design/tokens.css is up to date with tokens.json
 *   2. Every var(--x) in globals.css resolves to a defined token
 *   3. Every Tailwind class used in src/ is actually generated by Tailwind
 *   4. No hardcoded hex colors in src/ (outside the token source of truth)
 *
 * Usage: node scripts/check-tokens.mjs
 */

import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const ROOT = path.resolve(import.meta.dirname, "..");
const SRC = path.join(ROOT, "src");
const GLOBALS = path.join(SRC, "app/globals.css");
const TOKENS_CSS = path.join(SRC, "design/tokens.css");
const OUT_CSS = path.join(ROOT, "node_modules/.cache/design-tokens-check.css");

const problems = [];

function walk(dir, acc = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, acc);
    } else if (/\.(tsx|ts|css)$/.test(entry.name)) acc.push(full);
  }
  return acc;
}

// 1. generated tokens are current
try {
  execFileSync("node", [path.join(ROOT, "scripts/build-tokens.mjs"), "--check"], {
    cwd: ROOT,
    stdio: "pipe",
  });
} catch (err) {
  problems.push(`tokens.css is stale — run \`bun run tokens:build\`\n${err.stderr}`);
}

const globalsCss = fs.readFileSync(GLOBALS, "utf8");
const tokensCss = fs.readFileSync(TOKENS_CSS, "utf8");

// 2. every var() in globals.css resolves
const definedVars = new Set(
  [...tokensCss.matchAll(/^\s*(--[a-z0-9-]+)\s*:/gm)].map((m) => m[1])
);
for (const m of globalsCss.matchAll(/var\((--[a-zA-Z0-9-]+)/g)) {
  if (!definedVars.has(m[1])) {
    problems.push(`globals.css references undefined token ${m[1]}`);
  }
}

// 3. every class used in src/ is generated by Tailwind
fs.mkdirSync(path.dirname(OUT_CSS), { recursive: true });
execFileSync(
  "npx",
  ["@tailwindcss/cli", "-i", GLOBALS, "-o", OUT_CSS],
  { cwd: ROOT, stdio: "pipe" }
);
const compiled = fs.readFileSync(OUT_CSS, "utf8");

/**
 * Tailwind escapes special characters in class selectors with a backslash
 * (e.g. `border-champion/30` becomes `.border-champion\/30`), so build the
 * literal selector instead of a regex.
 */
function hasClass(compiled, cls) {
  const escaped = cls.replace(/([^a-zA-Z0-9_-])/g, "\\$1");
  const selector = `.${escaped}`;
  let from = 0;
  for (;;) {
    const idx = compiled.indexOf(selector, from);
    if (idx === -1) return false;
    const next = compiled[idx + selector.length];
    if (!next || !/[a-zA-Z0-9_-]/.test(next)) return true;
    from = idx + 1;
  }
}

const classTokens = new Set();
for (const file of walk(SRC)) {
  if (!file.endsWith(".tsx")) continue;
  const src = fs.readFileSync(file, "utf8");
  // className="..." and className={`...`}
  for (const m of src.matchAll(/className=(?:"([^"]*)"|\{`([^`]*)`\})/g)) {
    // Template-literal interpolations hold expressions, not class names.
    const raw = m[1] ?? m[2] ?? "";
    const cleaned = raw.replace(/\$\{[^}]*\}/g, " ");
    for (const c of cleaned.split(/\s+/)) {
      if (c) classTokens.add(c);
    }
  }
  // static lookup maps: { key: "a b c" }
  for (const m of src.matchAll(/:\s*"([a-z0-9:/\- ]+[a-z0-9])"/g)) {
    for (const c of m[1].split(/\s+/)) {
      if (c && c.includes("-") && !c.startsWith("--")) classTokens.add(c);
    }
  }
}

for (const cls of classTokens) {
  if (cls.includes("$") || cls.includes("{")) continue;
  if (!hasClass(compiled, cls)) {
    problems.push(`class "${cls}" is not generated by Tailwind (check the token exists)`);
  }
}

// 4. no hardcoded hex colors in source
for (const file of walk(SRC)) {
  if (file.endsWith("tokens.css") || file.endsWith("tokens.json")) continue;
  const src = fs.readFileSync(file, "utf8");
  src.split("\n").forEach((line, i) => {
    if (line.trim().startsWith("//") || line.trim().startsWith("*")) return;
    for (const m of line.matchAll(/#[0-9A-Fa-f]{3,8}\b/g)) {
      problems.push(
        `hardcoded color ${m[0]} in ${path.relative(ROOT, file)}:${i + 1} — use a design token`
      );
    }
  });
}

if (problems.length > 0) {
  console.error(`✖ design system check failed (${problems.length} problem(s)):\n`);
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}

console.log(
  `✔ design system check passed (${classTokens.size} classes, ${definedVars.size} tokens)`
);
